package com.epms.payroll.service;
import com.epms.payroll.dto.*; import com.epms.payroll.entity.User; import com.epms.payroll.exception.AuthenticationFailedException; import com.epms.payroll.repository.UserRepository; import com.epms.payroll.security.TokenService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository repo;private final PasswordEncoder enc;private final TokenService tokens; public AuthService(UserRepository r,PasswordEncoder e,TokenService t){repo=r;enc=e;tokens=t;} public LoginResponse login(LoginRequest x){User u=repo.findByUsername(x.username()).orElseThrow(()->new AuthenticationFailedException("Invalid username or password"));if(!u.isActive()||!enc.matches(x.password(),u.getPasswordHash()))throw new AuthenticationFailedException("Invalid username or password");return new LoginResponse(tokens.issue(u.getUsername()),u.getUsername(),u.getRole());}}
